// Counts and notation use the same hit predicate and positions as the audio scheduler.
function ctTimeActive(item){return (item.layers||[]).filter(l=>l.enabled);}
function ctTimeHits(item){return ctTimeActive(item).reduce((n,l)=>n+Array.from({length:l.sides},(_,i)=>jl(l,i)).filter(Boolean).length,0);}
function ctTimeSummary(item){const n=ctTimeActive(item).length;return `${n} active layer${n===1?'':'s'} · ${item.steps??item.measureSteps} steps · ${ctTimeHits(item)} hits`;}
function ctTimePoolLabel(item){return String(item.label).split(' · ')[0]+' · '+ctTimeSummary(item);}
function ctTimeFraction(value){for(let d=1;d<=4096;d++){const n=Math.round(value*d);if(Math.abs(n/d-value)<1e-8)return d===1?String(n):`${n}/${d}`;}return value.toFixed(6);}
function ctTimeRhythm(value){
 for(const base of [1,.5,.25,.125,.0625,.03125])for(const dots of [0,1,2])if(Math.abs(value-base*(dots===0?1:dots===1?1.5:1.75))<1e-8)return {base,dots,ratio:''};
 const base=[1,.5,.25,.125,.0625,.03125].reduce((best,n)=>Math.abs(Math.log2(value/n))<Math.abs(Math.log2(value/best))?n:best,.25);
 return {base,dots:0,ratio:ctTimeFraction(base/value).replace('/',':')};
}
function ctTimeRows(item){return ctTimeActive(item).map(layer=>({layer,events:Array.from({length:layer.sides},(_,vertex)=>({vertex,hit:jl(layer,vertex),position:Zl(layer,vertex,my(item)*1000,0,item.steps)})).sort((a,b)=>a.position-b.position)}));}
function ctTimePatternDetails(item,slot,repeat,drift,masterRepeat,masterDrift,mode,points){
 document.querySelector('.ct-time-details')?.remove();const dialog=document.createElement('dialog');dialog.className='ct-time-details';
 const close=document.createElement('button');close.textContent='CLOSE ×';close.onclick=()=>dialog.close();dialog.append(close);
 const title=document.createElement('h2');title.textContent=`Square ${slot+1} · Pattern details`;dialog.append(title);
 const pre=document.createElement('pre');
 const lines=[ctTimeSummary(item),`Meter ${item.meterN}/${item.meterD}; ${item.steps} steps per measure; each step = ${ctTimeFraction(item.meterN/item.meterD/item.steps)} of a whole note.`,`Tempo ${item.bpm} → ${item.middleBpm} → ${item.exitBpm} BPM; contour ${item.curve}`,`Square repeats ${repeat}; drift ${drift} ms per repeat. Full cycle repeats ${masterRepeat}; drift ${masterDrift} ms per cycle.`,`Universal Time ${mode}; control points (tempo multipliers): ${points.map(p=>Math.pow(2,p).toFixed(6)).join(', ')}`,'Hit positions below count from step 1; fractional positions fall between steps. Simultaneous hits in different layers count separately.'];
 for(const {layer,events} of ctTimeRows(item)){
  lines.push('',`L${layer.id} · ${ze[(layer.id-1)%ze.length].name} · ${layer.sides} points · source ${layer.source}`,`Swing ${layer.swing||0}%; rotation ${layer.hour}:${layer.minute}:${layer.second}; micro offset ${layer.microMs||0} ms; phase drift ${layer.phaseMs||0} ms/cycle`);
  lines.push(...events.map(e=>`${e.hit?'HIT ':'REST'} ${ctTimeFraction(e.position+1)} · point ${e.vertex+1} · ${layer.tones[e.vertex]||'VOICE'} · offset ${layer.pointOffsets?.[e.vertex]||0} steps`));
 }
 if(item.borrowedArrangement)lines.push('Borrowed pitched accompaniment is enabled; percussion staff shows rhythm layers only.',JSON.stringify(item.pitchWorld),`Progression ${item.progression}; ostinato ${item.ostinato}; cadence ${item.cadence}`);
 pre.textContent=lines.join('\n');dialog.append(pre);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();
}
function ctTimeFlash(slot,layer,vertex,position,steps){
 const query=`[data-time-slot="${slot}"] [data-time-layer="${layer}"][data-time-vertex="${vertex}"]`;
 document.querySelectorAll(query).forEach(n=>{n.classList.remove('ct-hit-flash');void n.getBoundingClientRect();n.classList.add('ct-hit-flash');});
 const arm=document.querySelector(`[data-time-slot="${slot}"] .composition-arm`);if(arm)arm.setAttribute('transform',`rotate(${position*360/steps} 50 50)`);
}
function ctTimeScore(item,playing=-1,slot=-1){
 const rows=ctTimeRows(item),times=[...new Set([0,item.steps,...Array.from({length:item.steps},(_,i)=>i),...rows.flatMap(r=>r.events.filter(e=>e.hit).map(e=>e.position))])].sort((a,b)=>a-b),positions=new Map();
 let cursor=80;times.forEach((at,i)=>{if(i)cursor+=Math.max(64,(at-times[i-1])*72);positions.set(at,cursor);});
 const width=Math.max(760,cursor+30),height=65+Math.max(1,rows.length)*112;
 const jsx=c.jsx,jsxs=c.jsxs,x=p=>positions.get(p),children=[];
 rows.forEach(({layer,events},row)=>{
  const y=100+row*112,color=['#f4c75f','#ef7bbd','#70d8a0','#7fc8ff'][(layer.id-1)%4];
  for(let line=0;line<5;line++)children.push(jsx('line',{x1:65,x2:width-12,y1:y-32+line*8,y2:y-32+line*8,stroke:'#657078'},`staff-${row}-${line}`));
  children.push(jsx('text',{x:8,y:y-37,fill:color,fontSize:12,children:`L${layer.id} ${ze[(layer.id-1)%ze.length].short}`},`label-${row}`));
  children.push(jsxs('g',{'aria-label':'Percussion clef',children:[jsx('rect',{x:22,y:y-30,width:4,height:25,fill:'#fff'}),jsx('rect',{x:31,y:y-30,width:4,height:25,fill:'#fff'})]},`clef-${row}`));
  const hits=events.filter(e=>e.hit),times=[...new Set([0,item.steps,...Array.from({length:item.steps},(_,i)=>i),...hits.map(e=>e.position)])].sort((a,b)=>a-b);
  times.slice(0,-1).forEach((at,i)=>{
   const sounding=hits.filter(e=>Math.abs(e.position-at)<1e-7),length=(times[i+1]-at)/item.steps*item.meterN/item.meterD,xx=x(at),yy=y-16;
   const rhythm=ctTimeRhythm(length),base=rhythm.base,flags=base<.25?Math.round(Math.log2(.25/base)):0;
   const value=ctTimeFraction(length),elements=[];
   if(sounding.length){elements.push(jsx('ellipse',{cx:xx,cy:yy,rx:5,ry:3.5,fill:base>=.5?'#111':color,stroke:color},'head'));
    if(base!==1)elements.push(jsx('line',{x1:xx+5,x2:xx+5,y1:yy,y2:yy-25,stroke:color},'stem'));
    for(let f=0;f<flags;f++)elements.push(jsx('path',{d:`M ${xx+5} ${yy-25+f*6} q 11 6 5 15`,fill:'none',stroke:color},`flag-${f}`));
    for(let dot=0;dot<rhythm.dots;dot++)elements.push(jsx('circle',{cx:xx+12+dot*5,cy:yy-3,r:1.5,fill:color},`dot-${dot}`));
   }else elements.push(jsx('text',{x:xx,y:yy+5,textAnchor:'middle',fill:'#9ea9b0',fontSize:12,children:'R'},'rest'));
   elements.push(jsx('text',{x:xx,y:y+22,textAnchor:'middle',fill:color,fontSize:10,children:value},'duration'));
   if(rhythm.ratio)elements.push(jsx('text',{x:xx,y:y-49,textAnchor:'middle',fill:color,fontSize:9,children:'Tuplet '+rhythm.ratio},'ratio'));
   children.push(jsxs('g',{'data-time-layer':layer.id,'data-time-vertex':sounding[0]?.vertex,className:Math.floor(at)===playing?'ct-score-now':'',children:elements},`event-${row}-${i}`));
  });
 });
 return jsxs('section',{className:'ct-time-score','data-time-slot':slot,children:[jsx('header',{children:`DRUM STAFF · ${item.meterN}/${item.meterD} · ${item.steps} steps · ${ctTimeSummary(item)}`}),jsx('div',{className:'ct-time-score-scroll',children:jsx('svg',{width,height,viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':'Percussion hits and rests across the measure',children})}),jsx('small',{children:'R = rest. Values below are fractions of a whole note. Values describe spacing to the next timing boundary, not drum decay. Dots and tuplet ratios describe irregular subdivisions. Colors identify layers; pitched accompaniment is not shown.'})]});
}

window.ctVerifyTimeSession=async function(){
 const pause=()=>new Promise(r=>setTimeout(r,100)),api=()=>window.ctTimeSessionTest,assert=(x,m)=>{if(!x)throw Error(m)},original=api().snapshot();
 try{
  const fixture=structuredClone(original);fixture.bpm=137;fixture.pattern[0][0]=true;
  fixture.ctResume.ideas=[{id:91,label:'Restore fixture',layers:structuredClone(fixture.layers),measureSteps:fixture.measureSteps,advanced:false}];
  fixture.ctResume.pool=[{id:92,layers:structuredClone(fixture.layers),pattern:structuredClone(fixture.pattern),steps:16,bpm:137,middleBpm:137,exitBpm:137,meterN:4,meterD:4,grouping:'1+1+1+1',curve:'s-curve',cadence:'OPEN',pitchWorld:{name:'test',cents:[0,400,700],equave:1200}}];
  fixture.ctResume.slots=[structuredClone(fixture.ctResume.pool[0]),null,null,null];
  assert(api().restore(fixture),'Time fixture rejected');await pause();
  const stored=JSON.parse(localStorage.getItem('circleTimeWorkspaceV1'));
  assert(stored.state.bpm===137&&stored.state.pattern[0][0]&&stored.state.ctResume.slots[0]?.id===92,'Time session omitted pattern/tempo/composition');
  api().reset();await pause();let now=api().snapshot();
  assert(!now.pattern.some(row=>row.some(Boolean))&&now.ctResume.slots.every(x=>x===null),'Time reset did not clear workspace');
  assert(now.ctResume.pool.length===1&&now.ctResume.ideas.length===1,'Time reset deleted pool');
  api().undo();await pause();now=api().snapshot();assert(now.bpm===137&&now.ctResume.slots[0]?.id===92,'Time reset undo incomplete');
  assert(api().restore(stored.state),'Time persisted session rejected');await pause();assert(!api().playing(),'Time restore started playback');
  assert(!api().restore({bpm:137}),'Malformed Time session accepted');
  return 'PASS: Time pattern/pool/composition/tempo persisted, Reset preserves pool, Undo restores workspace, restore stopped';
 }finally{api().restore(original);await pause()}
};
